// Функция для вычисления итогового балла из переменной KT_Tech_BTI
function calculateScore(ktVarName, resultVarName) {
    // Получаем объект Player
    var player = GetPlayer();
    
    // Получаем значение переменной KT_Tech_BTI
    var ktTechBTI = player.GetVar(ktVarName);
    console.log('KT_Tech_BTI:', ktTechBTI); // Отладка

    // Проверяем, получено ли корректное значение переменной KT_Tech_BTI
    if (ktTechBTI && typeof ktTechBTI === 'string') {
        // Преобразуем строку в массив
        var ktArray = ktTechBTI.slice(1, -1).split('],[').map(function(item) {
            return item ? item.split(',') : [];
        });

        console.log('KT Array:', ktArray); // Отладка
        
        // Правильные ответы для ячеек 1, 2 и 3
        var correctAnswers = [
            ['A', 'B'], // для ячейки 1
            ['C', 'D'], // для ячейки 2
            ['C', 'D']  // для ячейки 3
        ];
        
        // Переменные для хранения баллов каждой ячейки
        var score1 = 0, score2 = 0, score3 = 0, score4 = 0, score5 = 0;

        // Функция для проверки правильности ответов и подсчета баллов
        function calculateCellScore(cellAnswers, correctAnswers) {
            var correctCount = 0;
            var incorrectCount = 0;
            var seenAnswers = [];

            // Разбиваем каждый элемент на отдельные символы
            cellAnswers.forEach(function(answer) {
                answer.split('').forEach(function(char) {
                    if (correctAnswers.includes(char)) {
                        if (!seenAnswers.includes(char)) {
                            correctCount++;
                            seenAnswers.push(char);
                        }
                    } else {
                        incorrectCount++;
                    }
                });
            });

            // Рассчитываем баллы по правилам
            if (correctCount === 2 && incorrectCount === 0) return 2;
            if (correctCount === 1 && incorrectCount === 1) return 1;
            if (correctCount === 2 && incorrectCount === 1) return 1;
            return 0;
        }

        // Рассчитываем баллы для элементов 1, 2 и 3
        for (var i = 0; i < 3; i++) {
            var answers = ktArray[i] || [];
            console.log(`Answers for cell ${i + 1}:`, answers); // Отладка
            if (answers.length > 0) {
                if (i === 0) score1 = calculateCellScore(answers, correctAnswers[i]);
                if (i === 1) score2 = calculateCellScore(answers, correctAnswers[i]);
                if (i === 2) score3 = calculateCellScore(answers, correctAnswers[i]);
            }
        }

        // Рассчитываем баллы для элемента 4
        var answers4 = ktArray[3] || [];
        console.log('Answers for cell 4:', answers4); // Отладка
        if (answers4.length === 0) {
            // score остается 0
        } else if (answers4.includes('A')) {
            score4 = 1;
        } else {
            // score остается 0
        }

        // Рассчитываем баллы для элемента 5
        var answers5 = ktArray[4] || [];
        console.log('Answers for cell 5:', answers5); // Отладка
        if (answers5.length === 0) {
            // score остается 0
        } else {
            var patterns = ["A1", "B2", "C3", "D4"];
            var patternCount = 0;
            patterns.forEach(function(pattern) {
                if (answers5.includes(pattern)) {
                    patternCount++;
                }
            });
            if (patternCount === 4) {
                score5 = 3;
            } else if (patternCount >= 2) {
                score5 = 2;
            } else if (patternCount === 1) {
                score5 = 1;
            } else {
                // score остается 0
            }
        }

        // Суммируем все баллы
        var totalScore = score1 + score2 + score3 + score4 + score5;

        // Отладочные сообщения
        console.log('Scores:', {
            score1: score1,
            score2: score2,
            score3: score3,
            score4: score4,
            score5: score5,
            totalScore: totalScore
        });

        // Устанавливаем итоговый балл в переменную Check_Technology
        player.SetVar(resultVarName, totalScore);
    } else {
        console.error('Переменная KT_Tech_BTI не получена или имеет неверный формат.');
    }
}

// Пример вызова функции
var player = GetPlayer();
calculateScore('KT_Tech_BTI', 'Check_Technology');

// Функция для изменения значения переменной KT_Tech_BTI
function updateKT_Tech_BTI(ktVarName, questionNumberVarName, symbol) {
    // Получаем объект Player
    var player = GetPlayer();
    
    // Получаем значение переменной KT_Tech_BTI и Question_Number_3
    var ktTechBTI = player.GetVar(ktVarName);
    var questionNumber = player.GetVar(questionNumberVarName);
    
    // Проверяем, получено ли корректное значение переменной KT_Tech_BTI
    if (ktTechBTI && typeof ktTechBTI === 'string') {
        // Преобразуем строку в массив
        var ktArray = ktTechBTI.slice(1, -1).split('],[').map(function(item) {
            return item ? item.split(',') : [];
        });
        
        // Определяем индекс для работы
        var index = questionNumber - 6;
        
        // Проверяем, существует ли указанный индекс в массиве
        if (index >= 0 && index < ktArray.length) {
            // Устанавливаем новый символ в указанной ячейке
            ktArray[index] = [symbol];
            
            // Преобразуем массив обратно в строку
            var updatedKtTechBTI = '[' + ktArray.map(function(item) {
                return item.join(',');
            }).join('],[') + ']';
            
            // Устанавливаем обновленное значение переменной KT_Tech_BTI
            player.SetVar(ktVarName, updatedKtTechBTI);
        }
    } else {
        console.error('Переменная KT_Tech_BTI не получена или имеет неверный формат.');
    }
}

// Пример вызова функции
updateKT_Tech_BTI('KT_Tech_general', 'Question_Number_3', 'A');

